function openPublishModal(mode) {
  publishModalMode = mode === 'scope' ? 'scope' : 'publish';
  var scopeOnly = publishModalMode === 'scope';
  var st = Proto.getState();
  var meta = document.getElementById('pmPublishMeta');
  var titleEl = document.getElementById('pmModalTitle');
  var confirmBtn = document.getElementById('pmConfirmBtn');
