  if (!scopeOnly) {
    var first = Proto.isFirstPublish(st);
    var versionRow = document.getElementById('pmVersionRow');
    var versionHint = document.getElementById('pmVersionHint');
    var versionRequired = document.getElementById('pmVersionRequired');
    if (first) {
      versionRow.style.display = 'none';
      versionHint.style.display = 'block';
      document.getElementById('pmVersion').value = 'v1';
    } else {
      versionRow.style.display = '';
      versionHint.style.display = 'none';
      versionRequired.style.display = 'inline';
      document.getElementById('pmVersion').value = Proto.suggestPublishVersion(st);
    }
    document.getElementById('pmReleaseNote').value = '';
