function confirmPublish() {
  var scopeOnly = publishModalMode === 'scope';
  var st = Proto.getState();
  var note;
  var version;
  if (scopeOnly) {
    note = st.releaseNote || '可见范围变更';
    version = st.releaseVersion || st.version || 'v1';
  } else {
    note = document.getElementById('pmReleaseNote').value.trim();
    if (!note) { Proto.toast('请输入发版描述'); return; }
    var first = Proto.isFirstPublish(st);
    version = first ? 'v1' : document.getElementById('pmVersion').value.trim();
    if (!first && !version) { Proto.toast('请填写版本号'); return; }
  }
  var scope = document.querySelector('#publishModal input[name="pubscope"]:checked').value;
  if (scope === 'specific' && !selectedPermissionTargets.length) {
    Proto.toast('请选择组织范围');
    return;
  }
  closePublishModal();
  var scopeTag = document.getElementById('scopeTag');
  var tl = document.getElementById('publishTimeline');
  var now = new Date().toLocaleString('zh-CN', { hour12: false });
  var result = Proto.runAgentPublish({ scope: scope, version: version, releaseNote: note, permissionTargets: selectedPermissionTargets });
  if (result.status === 'error') {
    Proto.toast(result.toast || '发布失败');
    return;
  }
  document.getElementById('releaseVersionTitle').textContent = '当前版本 ' + version;

  if (result.status === 'review') {
    scopeTag.className = scope === 'public' ? 'scope-pill scope-public meta-tags' : 'scope-pill scope-specific meta-tags';
    scopeTag.textContent = scope === 'public' ? '🏢 全公司' : '👥 部门共享';
    document.getElementById('opsScope').textContent = scope === 'public' ? '全公司（审核中）' : '部门共享（审核中）';
    Proto.toast(result.toast || '已提交审核，智能体已进入审核流程');
    var tlPending = document.getElementById('tlPending');
    if (tlPending) {
      tlPending.outerHTML =
        '<div class="tl-item current" id="tlPending"><div class="tl-time">' + now + '</div><div class="tl-action">审核中 · ' + version + '</div><div class="tl-note">' + note.replace(/</g, '&lt;') + ' · <a href="' + Proto.href('08-audit-status.html') + '">查看审核进度</a></div></div>';
    }
    refreshStateUi();
    return;
  }
  if (scope === 'specific') {
    scopeTag.className = 'scope-pill scope-specific meta-tags';
    scopeTag.textContent = '👥 部门共享';
    document.getElementById('opsScope').textContent = '部门共享';
  } else {
    scopeTag.className = 'scope-pill scope-private meta-tags';
    scopeTag.textContent = '🔒 仅本人';
    document.getElementById('opsScope').textContent = '仅本人';
  }
  document.getElementById('opsShelf').textContent = '已上架';
  Proto.toast(result.toast);
  tl.insertAdjacentHTML('beforeend', '<div class="tl-item done"><div class="tl-time">' + now + '</div><div class="tl-action">已发布 · ' + version + '</div><div class="tl-note">' + note.replace(/</g, '&lt;') + '</div></div>');
  refreshStateUi();
}

